begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('aaaa8000-0000-4000-8000-000000000001','lineup-org@test.invalid','{"display_name":"Lineup Organizer"}'),
 ('aaaa8000-0000-4000-8000-000000000002','lineup-judge@test.invalid','{"display_name":"Lineup Judge"}'),
 ('aaaa8000-0000-4000-8000-000000000003','lineup-coach-a@test.invalid','{"display_name":"Lineup Trainer A"}'),
 ('aaaa8000-0000-4000-8000-000000000004','lineup-coach-b@test.invalid','{"display_name":"Lineup Trainer B"}'),
 ('aaaa8000-0000-4000-8000-000000000005','lineup-outsider@test.invalid','{"display_name":"Lineup Outsider"}');
insert into public.staff_accounts(id,email,display_name) select id,email,'Lineup Fixture' from auth.users where id::text like 'aaaa8000-%';
insert into public.staff_roles values('aaaa8000-0000-4000-8000-000000000001','organizer'),('aaaa8000-0000-4000-8000-000000000002','main_judge'),('aaaa8000-0000-4000-8000-000000000003','trainer'),('aaaa8000-0000-4000-8000-000000000004','trainer'),('aaaa8000-0000-4000-8000-000000000004','main_judge'),('aaaa8000-0000-4000-8000-000000000005','trainer');
create temp table lineup_fixture(match uuid,subteam_a uuid,subteam_b uuid,players_a uuid[],players_b uuid[],reserve_a uuid);
grant all on lineup_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.save_season('bbbb8000-0000-4000-8000-000000000001','Lineup Season',2026,'2026-01-01','2026-12-31');
select public.save_tour('cccc8000-0000-4000-8000-000000000001','bbbb8000-0000-4000-8000-000000000001','Lineup Tour',1,'2026-03-01','2026-03-03');
select public.create_stage_template('dddd8000-0000-4000-8000-000000000001','Lineup Format','{"nodes":[{"ordinal":1,"kind":"round_robin","group_count":1,"group_size":2}]}');
select public.configure_tour_stages('cccc8000-0000-4000-8000-000000000001','dddd8000-0000-4000-8000-000000000001',array['U13','U15','U17']::public.age_group[]);
select public.save_tournament_settings(gen_random_uuid(),'cccc8000-0000-4000-8000-000000000001',0,32,12,60,true,'Asia/Almaty');
do $$declare club uuid; sub uuid; person uuid; i integer; j integer; begin
 for i in 1..2 loop
  club:=gen_random_uuid(); perform public.save_team(club,'Lineup Club '||i,'Synthetic'); perform public.register_season_team('bbbb8000-0000-4000-8000-000000000001',club);
  select id into sub from public.subteams where team_id=club and age_group='U13';
  for j in 1..5 loop
   person:=gen_random_uuid(); perform public.save_player(person,club,'Hidden','Slot '||j,case when j in(1,3,5) then 'boy' else 'girl' end::public.player_gender,'2014-01-01','right','attack','junior'); perform public.add_roster_player('bbbb8000-0000-4000-8000-000000000001',sub,person);
  end loop;
 end loop;
end;$$;
select public.start_season('bbbb8000-0000-4000-8000-000000000001');
select public.generate_tour_draw('eeee8000-0000-4000-8000-000000000001','cccc8000-0000-4000-8000-000000000001','U13',0);
select public.publish_tour_draw('eeee8000-0000-4000-8000-000000000001',1);
insert into lineup_fixture(match,subteam_a,subteam_b) select id,subteam_a,subteam_b from public.team_matches where draw_id='eeee8000-0000-4000-8000-000000000001';
update lineup_fixture f set players_a=(select array_agg(p.id order by right(p.last_name,1)::integer) from public.roster_memberships m join public.players p on p.id=m.player_id where m.subteam_id=f.subteam_a and m.ended_at is null),players_b=(select array_agg(p.id order by right(p.last_name,1)::integer) from public.roster_memberships m join public.players p on p.id=m.player_id where m.subteam_id=f.subteam_b and m.ended_at is null);
select public.assign_team_trainer('aaaa8000-0000-4000-8000-000000000003',(select team_id from public.subteams where id=(select subteam_a from lineup_fixture)),array[(select subteam_a from lineup_fixture)]);
select public.assign_team_trainer('aaaa8000-0000-4000-8000-000000000004',(select team_id from public.subteams where id=(select subteam_b from lineup_fixture)),array[(select subteam_b from lineup_fixture)]);
do $$declare person uuid:=gen_random_uuid();club uuid;sub uuid;begin select subteam_a into sub from lineup_fixture;select team_id into club from public.subteams where id=sub;perform public.save_player(person,club,'Reserve','Boy','boy','2014-01-01','right','attack','junior');perform public.add_roster_player('bbbb8000-0000-4000-8000-000000000001',sub,person);update lineup_fixture set reserve_a=person;end;$$;
-- LINEUP_FIXTURE_END: shared by scripts/test-lineup-concurrency.mjs
select is((select count(*)::int from public.lineup_match_names(array[(select match from lineup_fixture)])),2,'authorized match participant names do not require private opposing-club access');
select is(public.get_lineup_status((select match from lineup_fixture))->>'revealed','false','Organizer sees status before reveal');
select throws_ok($$select public.submit_lineup('ffff8000-0000-4000-8000-000000000001',(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select players_a from lineup_fixture))$$,'42501','Assigned Trainer required','Organizer authority alone cannot submit either side');
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.submit_lineup(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select players_a[1:4] from lineup_fixture))$$,'22023','Five distinct lineup players required','partial lineup rejected');
select throws_ok($$select public.submit_lineup(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select array[players_a[1],players_a[2],players_a[1],players_a[4],players_a[5]] from lineup_fixture))$$,'22023','Five distinct lineup players required','duplicate player rejected');
select throws_ok($$select public.submit_lineup(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select array[players_a[2],players_a[1],players_a[3],players_a[4],players_a[5]] from lineup_fixture))$$,'22023','Eligible gendered roster player required','wrong slot gender rejected');
select throws_ok($$select public.submit_lineup(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select players_b from lineup_fixture))$$,'22023','Eligible gendered roster player required','opponent players cannot be submitted for own club');
select is(public.submit_lineup('ffff8000-0000-4000-8000-000000000001',(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select players_a from lineup_fixture))->>'a_submitted','true','assigned Trainer submits and locks own side');
select is((select count(*)::int from public.lineups where match_id=(select match from lineup_fixture)),1,'own submitted header visible');
select is((select count(*)::int from public.lineup_slots where lineup_id in('ffff8000-0000-4000-8000-000000000001','ffff8000-0000-4000-8000-000000000002')),5,'own slots visible before reveal');
select is((select count(*)::int from public.singles_games where match_id=(select match from lineup_fixture)),0,'no singles identities exist before joint reveal');
select is(public.get_lineup_status((select match from lineup_fixture))->>'lineup_version','1','first submission advances lineup version once');
select throws_ok($$select public.submit_lineup(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select players_a from lineup_fixture))$$,'22023','Lineup already locked','different request cannot edit locked side');
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*)::int from public.lineups where match_id=(select match from lineup_fixture)),0,'opponent Trainer plus Main Judge role cannot read hidden header');
select is((select count(*)::int from public.lineup_slots where lineup_id in('ffff8000-0000-4000-8000-000000000001','ffff8000-0000-4000-8000-000000000002')),0,'dual role cannot read hidden slots');
select is(public.get_lineup_status((select match from lineup_fixture))->>'a_submitted','true','dual role sees submission status only');
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*)::int from public.lineups where match_id=(select match from lineup_fixture)),0,'Organizer cannot inspect either hidden lineup');
select is((select count(*)::int from public.lineup_slots where lineup_id in('ffff8000-0000-4000-8000-000000000001','ffff8000-0000-4000-8000-000000000002')),0,'Organizer has no early slot visibility');
select is((select count(*)::int from public.audit_logs a cross join lineup_fixture f where a.action='lineup.submitted' and (a.after_state::text like '%'||f.players_a[1]::text||'%' or a.after_state ? 'original_players' or a.after_state ? 'hash')),0,'general audit contains no secret identities or brute-forceable lineup hash');
select throws_ok($$select public.replace_lineup_player(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select reserve_a from lineup_fixture),true,1)$$,'22023','Revealed active match required','official replacement cannot become a pre-reveal oracle');
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is(public.submit_lineup('ffff8000-0000-4000-8000-000000000002',(select match from lineup_fixture),(select subteam_b from lineup_fixture),(select players_b from lineup_fixture))->>'revealed','true','second submission jointly reveals both sides');
select is((select count(*)::int from public.lineups where match_id=(select match from lineup_fixture)),2,'both headers visible after reveal');
select is((select count(*)::int from public.lineup_slots where lineup_id in('ffff8000-0000-4000-8000-000000000001','ffff8000-0000-4000-8000-000000000002')),10,'all ten slots visible after reveal');
select is((select count(*)::int from public.singles_games where match_id=(select match from lineup_fixture)),5,'exactly five singles created with joint reveal');
select is(public.get_lineup_status((select match from lineup_fixture))->>'reveal_version','2','joint reveal has one committed version');
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select lives_ok($$select public.submit_lineup('ffff8000-0000-4000-8000-000000000001',(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select players_a from lineup_fixture))$$,'exact original retry is idempotent after reveal');
select throws_ok($$select public.submit_lineup('ffff8000-0000-4000-8000-000000000001',(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select array[reserve_a,players_a[2],players_a[3],players_a[4],players_a[5]] from lineup_fixture))$$,'22023','Lineup ID conflict','changed retry payload rejected');
select throws_ok($$select public.replace_lineup_player(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select reserve_a from lineup_fixture),true,2)$$,'42501','Draw permission required','ordinary Trainer cannot replace a locked player');
select throws_ok($$update public.lineup_slots set player_name='Bypass'$$,'42501',null,'direct locked slot edit denied');
select throws_ok($$delete from public.lineups$$,'42501',null,'direct locked lineup deletion denied');
select throws_ok($$update public.singles_games set status='finished'$$,'42501',null,'direct singles result bypass denied');
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.replace_lineup_player(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select reserve_a from lineup_fixture),true,1)$$,'22023','Lineup revision conflict','stale replacement revision rejected');
select throws_ok($$select public.replace_lineup_player(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select players_b[1] from lineup_fixture),true,2)$$,'22023','Eligible gendered roster player required','cross-club replacement rejected');
select lives_ok($$select public.replace_lineup_player('ffff8000-0000-4000-8000-000000000003',(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select reserve_a from lineup_fixture),true,2)$$,'Organizer replaces a pending singles player');
select is((select player_id from public.lineup_slots where lineup_id='ffff8000-0000-4000-8000-000000000001' and slot=1),(select reserve_a from lineup_fixture),'slot uses replacement');
select is((select player_a from public.singles_games where match_id=(select match from lineup_fixture) and slot=1),(select reserve_a from lineup_fixture),'pending singles uses replacement in same transaction');
select is((select original_players[1] from public.lineups where id='ffff8000-0000-4000-8000-000000000001'),(select players_a[1] from lineup_fixture),'original submitted request is retained');
select is((select old_player_id from public.lineup_replacements where id='ffff8000-0000-4000-8000-000000000003'),(select players_a[1] from lineup_fixture),'replacement preserves prior identity');
select lives_ok($$select public.replace_lineup_player('ffff8000-0000-4000-8000-000000000003',(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select reserve_a from lineup_fixture),true,2)$$,'same replacement retry does not require newer revision');
select is(public.get_lineup_status((select match from lineup_fixture))->>'lineup_version','3','replacement/retry changes version once');
select is((select count(*)::int from public.audit_logs where action='lineups.revealed' and entity_id=(select match from lineup_fixture)),1,'reveal audited once');
reset role;
update public.singles_games set status='in_progress' where match_id=(select match from lineup_fixture) and slot=1;
set local role authenticated;
select throws_ok($$select public.replace_lineup_player(gen_random_uuid(),(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select players_a[1] from lineup_fixture),true,3)$$,'22023','Pending singles and reason required','replacement denied once the singles starts');
reset role;
update public.team_matches set status='finished' where id=(select match from lineup_fixture);
set local role authenticated;
select lives_ok($$select public.replace_lineup_player('ffff8000-0000-4000-8000-000000000003',(select match from lineup_fixture),(select subteam_a from lineup_fixture),1,(select reserve_a from lineup_fixture),true,2)$$,'committed replacement retry remains idempotent after match completion');
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000005","role":"authenticated"}',true);
select throws_ok($$select public.get_lineup_status((select match from lineup_fixture))$$,'42501','Lineup access required','unassigned Trainer cannot query private lineup status');
select throws_ok($$select * from public.lineup_match_names(array[(select match from lineup_fixture)])$$,'42501','Lineup access required','unassigned Trainer cannot use match-name projection');
reset role;
update public.staff_accounts set active=false where id='aaaa8000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"aaaa8000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*)::int from public.lineups where match_id=(select match from lineup_fixture)),0,'inactive Trainer cannot read even revealed headers');
select is((select count(*)::int from public.lineup_slots where lineup_id in('ffff8000-0000-4000-8000-000000000001','ffff8000-0000-4000-8000-000000000002')),0,'inactive Trainer cannot read slots');
select is((select count(*)::int from public.singles_games where match_id=(select match from lineup_fixture)),0,'inactive Trainer cannot read singles');
select throws_ok($$select public.get_lineup_status((select match from lineup_fixture))$$,'42501','Lineup access required','inactive token cannot read private status');
select throws_ok($$select public.submit_lineup('ffff8000-0000-4000-8000-000000000001',(select match from lineup_fixture),(select subteam_a from lineup_fixture),(select players_a from lineup_fixture))$$,'42501','Assigned Trainer required','inactive token cannot retry a submission');
set local role anon;
select throws_ok($$select * from public.lineups$$,'42501',null,'anonymous lineup base table denied');
select throws_ok($$select * from public.lineup_slots$$,'42501',null,'anonymous lineup identities denied');
select throws_ok($$select public.get_lineup_status((select match from lineup_fixture))$$,'42501',null,'anonymous private status RPC denied');
select * from finish();
rollback;
